export function findById(id) { return SYMPTOMS.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return SYMPTOMS.slice();
  return SYMPTOMS.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return SYMPTOMS.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return SYMPTOMS.filter(x => x.enabled !== false); }
export const COUNT = SYMPTOMS.length;
